/* tests/tests.h -- shared C test utilities, stb style (C89)
 *
 * Test source layout:
 *   #include "ztest.h"          (which includes this and znet.h)
 *   TEST(foo) { ... }            -- defines static void test_foo(void)
 *   #include "foo_test.gen.inc"  -- generated by misc/gen_entries.lua
 *
 * The .gen.inc (entries table + main) is a build artifact regenerated by
 * just before compiling; never edit it.  Asserts abort on failure with
 * file:line; the runner prints one line per test.
 *
 * The test binary accepts test names as arguments (prefix match):
 *   ./tcp_test                  run every test
 *   ./tcp_test tcp_connect      run tests whose name starts with tcp_connect
 *   ./tcp_test @tcp_connect     run only the first match
 *   ./tcp_test '?tcp_connect'   match is optional
 */

#ifndef TESTS_H
#define TESTS_H

#include <assert.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* nested blocks re-declare loop vars (legal C89 scoping) */
#ifdef _MSC_VER
# pragma warning(disable : 4456)
#endif

#define test_log(...) fprintf(stderr, __VA_ARGS__)

/* TEST(name) -- define a test function: static void test_##name(void) */
#define TEST(name) static void test_##name(void)

/* asserteq -- abort if (a) != (b); ptrdiff_t holds pointer values whole,
 * unlike long (32-bit on LLP64 MSVC, which truncates and warns C4311) */
#define asserteq(a, b)                                                  \
    do {                                                                \
        ptrdiff_t _a = (ptrdiff_t)(a), _b = (ptrdiff_t)(b);             \
        if (_a != _b) {                                                 \
            test_log("FAIL %s:%d: %s == %ld, expected %ld\n", __FILE__, \
                     __LINE__, #a, (long)_a, (long)_b);                 \
            abort();                                                    \
        }                                                               \
        assert(_a == _b);                                               \
    } while (0)

/* assertok -- abort if (e) is false */
#define assertok(e)                                               \
    do {                                                          \
        if (!(e)) {                                               \
            test_log("FAIL %s:%d: %s\n", __FILE__, __LINE__, #e); \
            abort();                                              \
        }                                                         \
    } while (0)

/* assertstreq -- abort if strcmp(a, b) != 0 */
#define assertstreq(a, b)                                                   \
    do {                                                                    \
        const char *_sa = (a), *_sb = (b);                                  \
        if (strcmp(_sa, _sb) != 0) {                                        \
            test_log("FAIL %s:%d: '%s' != '%s'\n", __FILE__, __LINE__, _sa, \
                     _sb);                                                  \
            abort();                                                        \
        }                                                                   \
    } while (0)

/* test_skip -- mark the current test as skipped (e.g. no IPv6 loopback).
 * The test still counts as a pass but the runner reports SKIP. */
#define test_skip(...)         \
    do {                       \
        test_log(__VA_ARGS__); \
        test_log("\n");        \
        test_skipped = 1;      \
    } while (0)

static int test_skipped = 0;

/* ---- runner ---- */

typedef struct {
    const char *name;
    void (*fn)(void);
} test_entry;

/* test_run -- no args: run all; args: prefix match, '@' = first only,
 * '?' = optional (not found is not an error); "--list" prints test names
 * on stdout so the runner can isolate each test in its own process. */
static int test_run(const char *banner, const test_entry *entries, int argc,
                    char *argv[]) {
    int i, j;
    if (argc == 2 && strcmp(argv[1], "--list") == 0) {
        for (j = 0; entries[j].name; ++j) printf("%s\n", entries[j].name);
        return 0;
    }
    test_log("=== %s ===\n", banner);
    if (argc == 1) {
        const test_entry *e = entries;
        while (e->name) {
            test_log("- %s\n", e->name);
            test_skipped = 0;
            e->fn();
            test_log("  %s %s\n", e->name, test_skipped ? "SKIP" : "OK");
            ++e;
        }
        test_log("\n%s All tests passed!\n", banner);
        return 0;
    }
    for (i = 1; i < argc; ++i) {
        const char *name = argv[i];
        size_t      len = strlen(name);
        int         found = 0, only = 0, optional = 0;
        if (*name == '?') optional = 1, name++, len--;
        if (*name == '@') only = 1, name++, len--;
        for (j = 0; entries[j].name; ++j) {
            if (strlen(entries[j].name) >= len
                && strncmp(name, entries[j].name, len) == 0) {
                test_log("- %s\n", entries[j].name);
                test_skipped = 0;
                entries[j].fn();
                test_log("  %s %s\n", entries[j].name,
                         test_skipped ? "SKIP" : "OK");
                found = 1;
                if (only) break;
            }
        }
        if (!found && !optional) {
            test_log("Unknown test: %s\n", name);
            return 1;
        }
    }
    return 0;
}

#endif /* TESTS_H */
